draw:
var th = p.angle * Math.PI / 180;
var A = p.mag;
var Ax = A * Math.cos(th), Ay = A * Math.sin(th);
var pad = 40;
var span = 26;
var s = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (2 * span));
var ox = W / 2, oy = H / 2;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// grid
ctx.strokeStyle = C.faint;
for (var g = -span; g <= span; g += 5) {
  ctx.beginPath(); ctx.moveTo(X(g), Y(-span)); ctx.lineTo(X(g), Y(span)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(-span), Y(g)); ctx.lineTo(X(span), Y(g)); ctx.stroke();
}

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(X(-span), Y(0)); ctx.lineTo(X(span), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(-span)); ctx.lineTo(X(0), Y(span)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("x", X(span) - 12, Y(0) + 16);
ctx.fillText("y", X(0) + 8, Y(span) + 14);

// component legs
ctx.strokeStyle = C.figure;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Ax), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(Ax), Y(0)); ctx.lineTo(X(Ax), Y(Ay)); ctx.stroke();
ctx.setLineDash([]);

// right-angle tick at the corner
var d = 7 * (Ax >= 0 ? -1 : 1), e = 7 * (Ay >= 0 ? -1 : 1);
ctx.beginPath();
ctx.moveTo(X(Ax) + d, Y(0));
ctx.lineTo(X(Ax) + d, Y(0) + e);
ctx.lineTo(X(Ax), Y(0) + e);
ctx.stroke();

// the vector itself
var ax = X(Ax), ay = Y(Ay);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(ax, ay); ctx.stroke();
var hl = 10, ang = Math.atan2(ay - Y(0), ax - X(0));
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(ax, ay);
ctx.lineTo(ax - hl * Math.cos(ang - 0.4), ay - hl * Math.sin(ang - 0.4));
ctx.lineTo(ax - hl * Math.cos(ang + 0.4), ay - hl * Math.sin(ang + 0.4));
ctx.closePath(); ctx.fill();

// angle arc
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
ctx.beginPath();
ctx.arc(X(0), Y(0), 26, 0, -th, th > 0);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("A", (X(0) + ax) / 2 - 14, (Y(0) + ay) / 2 - 6);
ctx.fillText("Ax = " + Ax.toFixed(2), X(Ax / 2) - 22, Y(0) + (Ay >= 0 ? 18 : -8));
ctx.fillText("Ay = " + Ay.toFixed(2), X(Ax) + (Ax >= 0 ? 8 : -60), Y(Ay / 2));
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 30, Y(0) - (th > 0 ? 10 : -20));

out.note = "A = " + A.toFixed(1) + " at " + p.angle.toFixed(0) + " deg   ->   Ax = A cos = " + Ax.toFixed(2) + ",  Ay = A sin = " + Ay.toFixed(2) + "   (check: sqrt(Ax^2+Ay^2) = " + Math.sqrt(Ax * Ax + Ay * Ay).toFixed(2) + ")";
